//**floor proximity
prox = prox - above(vy,0.28)*prox*2;
q32 = 0.58 + 0.21*prox;
monitor = prox;

//****tunnel rotation
rota = rota +0.017*below(index%16,8)/fps*30;
rota1 = rota1*dec_med + (1-dec_med)*rota;
q7 = rota1;

//****tunnel speed
